const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=v=>JSON.stringify(v,null,2);
const short=v=>typeof v==='object'?JSON.stringify(v):String(v??'—');
const $=s=>document.querySelector(s);
const navItems=[['dashboard','home','Dashboard','workspace'],['projects','folder','Projects','workspace'],['import','upload','Import','workflow'],['check','check','Check','workflow'],['generation','spark','Generation','workflow'],['agents','agents','AI Agents','workflow'],['configuration','settings','Configuration','manage'],['rules','rules','Rules Manager','manage'],['reports','report','Reports','manage']];
const verificationProfiles=[['low_level_requirements','Low-Level Requirements','Checks each low-level requirement against approved limits, types, domains, and source evidence.'],['low_level_tests','Low-Level Tests','Checks low-level test observations against the requirement contract and flags missing evidence.'],['high_level_tests','High-Level Tests','Checks high-level test coverage against approved requirement links and observed results.']];
const verificationModes=[['deterministic','Deterministic configuration','Rules, schemas, limits, and source links. Reproducible and reviewable.'],['llm_assisted','LLM-assisted proposal','The LLM proposes explanations or links; a human review remains required.']];
const testLevels=[['LLR','Low-Level Requirements','Requirement wording, identifiers, types, limits, and source evidence.'],['LLT','Low-Level Tests','Detailed unit or parameter tests linked to low-level requirements.'],['HLT','High-Level Tests','System or feature tests linked to high-level behavior and acceptance evidence.']];
function requirementLevel(item){const raw=String(item.level||item.test_level||item.type||item.category||item.id||'').toUpperCase();if(raw.includes('HLT')||raw.includes('HIGH'))return 'HLT';if(raw.includes('LLT')||raw.includes('LOW_LEVEL_TEST'))return 'LLT';return 'LLR'}
function levelCards(items,emptyText='No records yet'){return testLevels.map(([level,label,description])=>{const rows=items.filter(item=>requirementLevel(item)===level);return `<section class="card level-card"><div class="level-card-head"><div><span class="level-code">${level}</span><h3>${label}</h3></div><span class="inline-count">${rows.length}</span></div><p>${description}</p>${rows.length?table(['ID','Description','Source'],rows.slice(0,8).map(item=>tr([`<strong>${esc(item.id||item.name||'—')}</strong>`,esc(item.text||item.description||item.name||'—'),esc(item.source||item.source_ref||'—')]))):empty(emptyText,'Import or configure records for this level.','layers')}</section>`}).join('')}
let scope=JSON.parse(localStorage.getItem('sx-scope')||'{"client":"default","project":"default"}');
let S=null,route='dashboard',tab={},stage=null,files=[],selectedRequirements=new Set(),models=[],modelsConnected=false,modelsError='',downloadJob=null,agentDrafts={},agentRole=null,fieldCollection='parameters',fieldIndex=0,filter='All',query='',page=1,editorTimer=null,editorPending=null,editorSave=Promise.resolve(),reviewer=sessionStorage.getItem('sx-reviewer')||'',busy=false;
const content=$('#content');
function btn(label,action,ico='',type='',extra=''){return `<button class="btn ${type}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`}
function badge(text,color=''){return `<span class="badge ${color}">${esc(text)}</span>`}
function heading(title,subtitle='',actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function empty(title,text='',ico='file',action=''){return `<div class="empty"><span class="empty-icon">${icon(ico)}</span><strong>${title}</strong><p>${text}</p>${action}</div>`}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
const tr=cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
function tabs(key,labels){const active=tab[key]||labels[0];return `<div class="tabs" role="tablist" aria-label="${esc(key)}">${labels.map(label=>`<button class="tab ${active===label?'active':''}" role="tab" aria-selected="${active===label}" data-action="tab" data-key="${key}" data-value="${esc(label)}">${esc(label)}</button>`).join('')}</div>`}
function note(text,type=''){return `<div class="note ${type}">${text}</div>`}
function field(label,id,value='',type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function textArea(label,id,value,height=260){return `<div class="field"><label for="${id}">${label}</label><textarea id="${id}" class="editor-text" rows="12">${esc(value)}</textarea></div>`}
function options(values,current){return values.map(v=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(v)}</option>`).join('')}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',error?9000:4500)}
async function request(path,data){const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...scope,...data})});const result=await res.json();if(!res.ok)throw new Error(result.error||'Request failed');return result}
async function action(path,data={},message=''){if(busy)return;busy=true;document.body.classList.add('busy');try{S=await request(path,data);sync();render();if(message)toast(message);return true}catch(e){toast(e.message,true);return false}finally{busy=false;document.body.classList.remove('busy')}}
async function load(){const res=await fetch('/api/state?'+new URLSearchParams(scope));const result=await res.json();if(!res.ok)throw new Error(result.error);S=result;await refreshModels(false);sync();render()}
function sync(){if(!S)return;$('#client-select').innerHTML=S.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===scope.client?'selected':''}>${esc(c.name)}</option>`).join('');const names=[...new Set([scope.project,...S.projects.map(p=>p.name)])];$('#project-select').innerHTML=options(names,scope.project);$('#sidebar-client').textContent=S.client.name;$('#reviewer-label').textContent=reviewer||'Local workspace';$('#avatar').textContent=reviewer?reviewer.split(/\s+/).map(p=>p[0]).join('').slice(0,2).toUpperCase():'SX';$('#notification-dot').hidden=!(S.draft.tester_json&&!S.approved);const groups=[['workspace','Workspace'],['workflow','Workflow'],['manage','Manage']];$('#nav').innerHTML=groups.map(([group,title])=>`<div class="nav-section-label">${title}</div>${navItems.filter(x=>x[3]===group).map(([id,ico,label])=>`<a class="nav-item ${route===id||(route==='finding'&&id==='check')?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='import'&&!S.documents.length?'<span class="nav-badge">Start</span>':''}${id==='check'&&S.approved&&!S.draft.verification_output?'<span class="nav-badge">Next</span>':''}</a>`).join('')}`).join('')}
function contract(){try{return JSON.parse(S.draft.tester_editor||'{}')}catch{return S.draft.tester_json||{}}}
function verification(){return S.draft.verification_output||{}}
function generation(){return S.draft.generation_output||{}}
function requireApproval(){return `<div class="card">${empty('Review your source contract first','Import an engineering document, review the extracted JSON, and record your approval before continuing.','shield',btn('Open Import','goto-import','upload','primary'))}</div>`}
function workflowQuickbar(){if(!S)return;const hasSource=S.documents.length>0||!!S.draft.tester_json;const stages=[['import','Import','Add source'],['understand','Understand','Extract structure'],['review','Review','Approve JSON'],['check','Verify','Run checks']];const current=route==='import'?'import':route==='check'?'check':route==='generation'?'review':S.approved?'check':S.draft.tester_json?'review':hasSource?'understand':'import';const next=stages.findIndex(([id])=>id===current);$('#workflow-quickbar').innerHTML=`<div class="workflow-inner"><div class="workflow-title"><span class="workflow-kicker">WORKFLOW</span><strong>${esc(stages[next][1])}</strong><small>${esc(stages[next][2])}</small></div><div class="workflow-steps">${stages.map(([id,label,detail],i)=>`<a class="workflow-step ${id===current?'active':''} ${i<next?'done':''}" href="${id==='understand'||id==='review'?'#import':'#'+id}" ${id===current?'aria-current="step"':''}><span class="workflow-number">${i<next?icon('tick'):i+1}</span><span><strong>${label}</strong><small>${detail}</small></span></a>${i<stages.length-1?'<span class="workflow-connector"></span>':''}`).join('')}<button class="workflow-cta" data-action="${current==='import'?'goto-import':current==='understand'?'goto-import':current==='review'?'goto-import':'goto-check'}">${current==='import'?'Start import':current==='understand'?'Open understanding':current==='review'?'Review JSON':'Run verification'}${icon('arrow')}</button></div></div>`}
function verificationSetup(){const output=S.draft.verification_output||{};const profile=localStorage.getItem('sx-verification-profile')||output.verification_profile||'low_level_requirements';const mode=localStorage.getItem('sx-verification-mode')||output.verification_mode||'deterministic';const selected=verificationProfiles.find(x=>x[0]===profile)||verificationProfiles[0];return `<section class="card verification-setup"><div class="verification-setup-heading"><div><span class="workflow-kicker">PRECONFIGURED CHECK</span><h2>Choose what you want to verify</h2><p>Start with a ready-made aerospace profile. You can change it before every run.</p></div>${badge('Ready to run','green')}</div><div class="verification-setup-grid"><label class="verification-choice"><span>Verification profile</span><select id="verification-profile">${verificationProfiles.map(([id,label])=>`<option value="${id}" ${id===profile?'selected':''}>${label}</option>`).join('')}</select><small id="verification-profile-help">${esc(selected[2])}</small></label><label class="verification-choice"><span>Verification method</span><select id="verification-mode">${verificationModes.map(([id,label])=>`<option value="${id}" ${id===mode?'selected':''}>${label}</option>`).join('')}</select><small>${esc(verificationModes.find(x=>x[0]===mode)?.[2]||verificationModes[0][2])}</small></label></div></section>`}
function verificationResultMeta(){const output=S.draft.verification_output||{};const config=output.configuration;if(!config)return '';return `<section class="card verification-result-meta"><div><span class="workflow-kicker">LAST RUN</span><strong>${esc(config.profile)}</strong><small>${esc(config.method)}</small></div><div class="verification-result-stats">${badge(output.status||'Not run',output.status==='completed'?'green':'orange')}${output.llm_provider?badge(`Provider: ${output.llm_provider}`,'blue'):''}</div>${output.llm_explanation?`<details class="verification-explanation"><summary>Open LLM review note</summary><p>${esc(output.llm_explanation)}</p></details>`:''}</section>`}
function verificationMethodFields(){const mode=localStorage.getItem('sx-verification-mode')||S.draft.verification_output?.verification_mode||'deterministic',c=contract(),params=c.parameters||[];return `<section class="card verification-method-fields"><div class="card-heading"><div><h3>${mode==='llm_assisted'?'Tell the LLM what to review':'Define the deterministic check'}</h3><p class="footnote">${mode==='llm_assisted'?'Your prompt is sent to the configured local Ollama model together with structured findings.':'Choose a parameter and expected value. The value is stored with the verification run for review.'}</p></div>${badge(mode==='llm_assisted'?'Ollama prompt':'Manual rule','blue')}</div>${mode==='llm_assisted'?textArea('Review prompt','verification-prompt','Focus on missing evidence, traceability, and explain every open finding.',140):`<div class="form-grid"><div class="field"><label for="verification-parameter">Parameter to check</label><select id="verification-parameter"><option value="">Use all approved parameters</option>${params.map(p=>`<option value="${esc(p.name)}">${esc(p.name)} · ${esc(p.requirement_id||'')}</option>`).join('')}</select></div>${field('Expected value or rule','verification-expected','','text','placeholder="Example: <= 10, enum ACTIVE, or required"')}</div>`}</section>`}
function render(){if(!S)return;route=(location.hash.slice(1).split('/')[0]||'dashboard');if(!navItems.some(x=>x[0]===route)&&route!=='finding')route='dashboard';sync();workflowQuickbar();const renderers={dashboard:dashboardOverview,projects:projectsOverview,import:importPage,check:checkPage,generation:generationPage,agents:agentsPage,configuration:configurationPage,rules:rulesPage,reports:reportsPage,finding:findingPage};content.innerHTML=renderers[route]();if(route==='check'&&S.approved)content.innerHTML=verificationSetup()+verificationMethodFields()+(S.draft.verification_output?verificationResultMeta():'')+content.innerHTML;document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));setupDrop();}
function dashboardOverview(){const c=contract(),v=verification(),g=generation(),findings=v.findings||[],errors=findings.filter(f=>String(f.severity).toLowerCase()==='error'&&f.status!=='PASS').length,passed=findings.filter(f=>f.status==='PASS').length,history=(S.runs||[]).length+(S.documents||[]).length;const metrics=[['folder',S.projects.length||1,'Projects','Open project workspaces'],['file',S.documents.length,'Files','Imported and linked sources'],['clock',history,'History','Documents and agent runs'],['x',errors,'Errors','Open verification findings'],['circlecheck',passed,'Passed','Checks passed'],['check',findings.length?'3':'0','Check levels','LLR · LLT · HLT']];return heading('Dashboard','See the health of your engineering workspace at a glance.',btn('Import File','goto-import','upload','primary'))+`<section class="hero"><h2>What would you like to do?</h2><p>Move from source files to reviewed requirements, tests, and traceable reports.</p><div class="actions">${btn('Import source','goto-import','upload','primary')}${btn('Generate tests','goto-generation','spark')}${btn('Run verification','goto-check','check')}${btn('Open reports','goto-reports','report')}</div></section><div class="kpis dashboard-kpis">${metrics.map(([ico,value,label,help])=>`<div class="card kpi"><span class="kpi-icon">${icon(ico)}</span><div><div class="kpi-value">${value}</div><div class="kpi-label">${label}</div><small>${help}</small></div></div>`).join('')}</div><section class="card dashboard-levels"><div class="card-heading"><div><h3>Verification levels</h3><p class="footnote">Keep requirement, low-level test, and high-level test evidence visible together.</p></div>${badge(S.approved?'Contract approved':'Needs review',S.approved?'green':'orange')}</div><div class="level-strip">${testLevels.map(([level,label])=>`<div><strong>${level}</strong><span>${label}</span><b>${(c.requirements||[]).filter(r=>requirementLevel(r)===level).length}</b></div>`).join('')}</div></section><div class="dashboard-grid"><section class="card"><div class="card-heading"><h3>Recent activity</h3><a href="#reports">View history ${icon('arrow')}</a></div>${S.documents.length?table(['File','Type','Status'],S.documents.slice(-7).reverse().map(d=>tr([`<span class="file-cell">${icon('file')}${esc(d.name)}</span>`,d.guidance?'Guidance':'Source',badge('Saved','green')]))):empty('Your workspace is ready','Import a source file to start the workflow.','folder',btn('Import first source','goto-import','upload','primary'))}</section><section class="card"><div class="card-heading"><h3>Next step</h3>${badge(modelsConnected?'Ollama connected':'Ollama unavailable',modelsConnected?'green':'orange')}</div>${!S.documents.length?note('Start by importing a requirement, test, design, or data file.'):!S.approved?note('Review and approve the canonical JSON before verification or test generation.','warning'):!v.findings?note('The contract is ready. Run a check or generate traceable tests.','success'):note(`${errors} open errors · ${passed} passed checks. Open Reports for linked evidence.`)}</section></div>`}
function dashboard(){const c=contract(),v=verification(),g=generation(),documents=S.documents;const metric=[['folder',S.projects.length||1,'Projects'],['file',documents.length,'Documents'],['rules',(g.cases||[]).length,'Test Cases'],['shield','—','Traceability']];return heading('Dashboard',`Welcome back${reviewer?', '+esc(reviewer.split(' ')[0]):''}. Here is your overview.`)+`<section class="hero"><h2>Start a new workflow</h2><p>Import a file, let AI agents understand, check or generate tests.</p><div class="actions">${btn('Import File','goto-import','plus','primary')}${btn('Generate Tests','goto-generation','spark')}${btn('Run Check','goto-check','check')}</div></section><div class="kpis">${metric.map(([ico,value,label])=>`<div class="card kpi"><span class="kpi-icon">${icon(ico)}</span><div><div class="kpi-value">${value}</div><div class="kpi-label">${label}</div></div></div>`).join('')}</div><div class="dashboard-grid"><section class="card"><div class="card-heading"><h3>Recent Activities</h3><a href="#projects">View All ${icon('arrow')}</a></div>${documents.length?table(['File / Project','Type','Status','Source'],documents.slice(-7).reverse().map(d=>tr([`<span class="file-cell">${icon('file')}${esc(d.name)}</span>`,d.guidance?'Guidance':'Import',badge('Saved','green'),esc(scope.project)]))):empty('Your workspace is ready','Import your first document to begin building project evidence.','folder',btn('Import first file','goto-import','upload','primary'))}</section><section class="card"><div class="card-heading"><h3>Agent System</h3><span class="inline-count">9 agents</span></div><div class="agent-mini"><div class="agent-line">${icon('agents')}Ollama<span>${modelsConnected?'Connected':'Not checked'}</span></div><div class="agent-line">${icon('shield')}Review gate<span>${S.approved?'Approved':'Awaiting import'}</span></div><div class="agent-line">${icon('rules')}Requirements<span>${(c.requirements||[]).length}</span></div><div class="agent-line">${icon('check')}Findings<span>${(v.findings||[]).filter(f=>f.status!=='PASS').length}</span></div><div class="mt">${btn('Manage agents','goto-agents','arrow','')}</div></div></section></div><p class="footnote">Metrics reflect saved project evidence. Traceability execution coverage has not been measured.</p>`}
function projectsOverview(){const names=[...new Set([scope.project,...S.projects.map(p=>p.name)])],c=contract(),records=[...(c.requirements||[]),...(c.parameters||[])];return heading('Projects','Every project keeps its own sources, contract, checks, tests, and reports.',btn('New Project','new-project','plus','primary'))+`<div class="grid-three">${names.map(name=>`<section class="card project-card ${name===scope.project?'selected-project':''}"><span class="project-icon">${icon('folder')}</span><h3>${esc(name)}</h3><p>${esc(S.client.name)} · ${esc(S.client.profile)} profile</p><div class="project-footer">${badge(name===scope.project?'Open now':'Workspace',name===scope.project?'teal':'')}${btn(name===scope.project?'Refresh project':'Open project','open-project','arrow','small',`data-project="${esc(name)}"`)}</div></section>`).join('')}</div><section class="project-levels"><div class="card-heading"><div><h2>${esc(scope.project)} workspace</h2><p class="footnote">Choose a level to see the work that belongs to this project.</p></div>${badge(S.approved?'Approved contract':'Review required',S.approved?'green':'orange')}</div><div class="grid-three">${levelCards(records,'No requirements or tests mapped to this level.')}</div></section><section class="card mt"><div class="card-heading"><h3>Project files and history</h3><span class="inline-count">${S.documents.length} files · ${(S.runs||[]).length} runs</span></div>${S.documents.length?table(['File','Kind','Status'],S.documents.map(d=>tr([`<span class="file-cell">${icon('file')}${esc(d.name)}</span>`,d.guidance?'Client guidance':'Engineering source',badge('Linked','green')]))):empty('No project files','Import requirements, tests, design files, or rule spreadsheets to build this project.','file',btn('Import files','goto-import','upload','primary'))}</section>`}
function projects(){const names=[...new Set([scope.project,...S.projects.map(p=>p.name)])];return heading('Projects',`Engineering workspaces for ${esc(S.client.name)}.`,btn('New Project','new-project','plus','primary'))+`<div class="grid-three">${names.map(name=>`<section class="card project-card"><span class="project-icon">${icon('folder')}</span><h3>${esc(name)}</h3><p>${esc(S.client.name)} · ${esc(S.client.profile)} profile</p><div class="project-footer">${badge(name===scope.project?'Current project':'Workspace',name===scope.project?'teal':'')}${btn('Open project','open-project','arrow','small',`data-project="${esc(name)}"`)}</div></section>`).join('')}</div><section class="card mt"><div class="card-heading"><h3>Project Documents</h3><span class="inline-count">${S.documents.length} documents</span></div>${S.documents.length?table(['Document','Source ID','Type'],S.documents.map(d=>tr([`<span class="file-cell">${icon('file')}${esc(d.name)}</span>`,`<span class="mono muted">${esc(d.hash.slice(0,16))}…</span>`,badge(d.guidance?'Guidance':'Evidence','blue')]))):empty('No documents yet','Import files into this project to keep source evidence and review history together.','file',btn('Import documents','goto-import','upload','primary'))}</section>`}
function stepper(){const i=stage??S.draft.import_step??0;const steps=[['Upload','Choose the source file'],['Understand','Extract its structure'],['Review','Check the generated JSON'],['Continue','Approve and move on']];return `<div class="card stepper" aria-label="Import progress"><div class="stepper-header"><div><strong>Import workflow</strong><small>Follow these steps to prepare your engineering evidence.</small></div><span class="step-counter">Step ${i+1} of ${steps.length}</span></div><div class="stepper-track">${steps.map(([name,desc],n)=>`${n?'<span class="step-line"></span>':''}<button class="step ${n===i?'active':''} ${n<i?'done':''}" data-action="stage" data-index="${n}" ${n>0&&!S.draft.tester_json?'disabled':''} aria-current="${n===i?'step':'false'}"><span class="step-circle">${n<i?icon('tick'):n+1}</span><span class="step-copy"><strong>${name}</strong><small>${desc}</small></span></button>`).join('')}</div></div>`}
function importPage(){const i=stage??S.draft.import_step??0;const titles=['Import','AI Understanding','Review & Edit','Import Complete'];const subtitles=['Upload any supported file. We will understand and convert it to canonical JSON.','Extract structure and content using your configured provider.','Validate and edit the generated canonical JSON.','Your reviewed source contract is ready for the next step.'];return heading(titles[i],subtitles[i])+stepper()+[uploadPage,understandingPage,reviewPage,completePage][i]()}
function uploadPage(){return `<div class="workspace-grid"><section class="card upload-panel"><div class="dropzone" id="dropzone"><div class="upload-icon">${icon('cloud')}</div><h3>Drag & drop your file here</h3><button class="browse-link" data-action="browse">or click to browse</button><input type="file" id="file-input" multiple accept=".xlsx,.xls,.csv,.pdf,.docx,.ptu,.xml,.json,.c,.h,.cpp,.cc,.hpp,.txt,.md" hidden><p>Supports: XLSX, XLS, CSV, PDF, DOCX, PTU, XML, JSON, C/C++, TXT and MD.</p><div class="uploaded-files">${files.map((f,i)=>`<div class="file-item">${icon('file')}<div><strong>${esc(f.name)}</strong><small>${(f.size/1024).toFixed(1)} KB · ${esc(f.name.split('.').pop().toUpperCase())}</small></div><button class="remove-file" data-action="remove-file" data-index="${i}" aria-label="Remove ${esc(f.name)}">${icon('x')}</button></div>`).join('')}</div></div><details class="option-details"><summary>Paste requirements or structured JSON</summary><div class="field mt"><label for="paste-source">Source content</label><textarea id="paste-source" rows="5" placeholder="The system shall…"></textarea></div></details>${btn('Continue','convert','arrow','primary wide')}</section><aside class="card option-panel"><h3>Import Options</h3><div class="field inline"><label for="document-type">Document Type</label><select id="document-type" disabled><option>Auto Detect</option></select></div><div class="field inline"><label for="import-provider">Understanding</label><select id="import-provider">${options(['deterministic','ollama','openai','azure_openai'],'deterministic')}</select></div><div class="field inline"><label>Client Mapping</label><span class="badge teal">${esc(S.client.name)}</span></div><label class="check-field"><input id="as-guidance" type="checkbox">Use as client guidance</label><details class="option-details" open><summary>Advanced Options</summary><label class="check-field"><input type="checkbox" checked disabled>Preserve original sources</label><label class="check-field"><input type="checkbox" checked disabled>Include source metadata</label><p>10 MB per file · 50 MB combined.<br>Scanned PDFs require OCR before upload. Embedded image extraction is adapter dependent.</p></details>${note('Your client mappings apply automatically. Source files are retained separately from edited JSON.')}</aside></div>`}
function dataTable(items){if(!items.length)return empty('No structured records','The original source remains available for review. Add missing information in the JSON review step.','layers');const keys=[...new Set(items.flatMap(x=>Object.keys(x)))].filter(k=>!['attributes','metadata','content'].includes(k)).slice(0,8);return table(keys.map(k=>esc(k.replaceAll('_',' '))),items.map(r=>tr(keys.map(k=>esc(short(r[k]))))))}
function understandingPage(){const c=contract(),t=tab.understand||'Table View';const sources=c.sources||[],records=(c.parameters||[]).length?c.parameters:c.requirements||[];return `<div class="workspace-grid"><section class="card"><div class="card-heading"><h3>Source Preview</h3>${badge(`${sources.length} source${sources.length===1?'':'s'}`,'blue')}</div>${tabs('understand',['Table View','Raw Content','Structure','Processing Logs'])}<div class="panel-body">${t==='Table View'?dataTable(records):t==='Raw Content'?sources.map(s=>`<h3 class="mb">${esc(s.name)}</h3><pre class="source-preview">${esc(s.content||'No source text')}</pre>`).join(''):t==='Structure'?`<pre class="code-block">${esc(pretty(Object.fromEntries(Object.entries(c).map(([k,v])=>[k,Array.isArray(v)?`${v.length} records`:typeof v]))))}</pre>`:`<pre class="code-block">${esc(pretty(c.audit||[]))}</pre>`}</div></section><aside class="card card-pad"><h3>AI Analysis</h3><div class="analysis-list"><div class="analysis-row">${icon('circlecheck')}<div>File format detected<small>${sources.map(s=>esc(s.name.split('.').pop().toUpperCase())).join(', ')||'No source'}</small></div></div><div class="analysis-row">${icon('circlecheck')}<div>Structure extracted<small>${records.length} structured records</small></div></div><div class="analysis-row">${icon('circlecheck')}<div>Client mappings applied<small>${esc(S.client.name)} · revision ${S.client.revision}</small></div></div><div class="analysis-row">${icon('shield')}<div>Human review required<small>Confirm the interpretation and constraints.</small></div></div></div><h3 class="mt">Detected Entities</h3><div class="tags">${badge(`${(c.requirements||[]).length} Requirements`)}${badge(`${(c.parameters||[]).length} Parameters`)}${badge(`${(c.samples||[]).length} Observed values`)}</div>${(c.warnings||[]).map(w=>note(esc(w),'warning')).join('')}<p class="footnote">Extracted content is a proposal. No confidence score is inferred or fabricated.</p></aside></div><div class="flow-footer">${btn('Back','stage','','', 'data-index="0"')}${btn('Continue to Review','stage','arrow','primary','data-index="2"')}</div>`}
function reviewPage(){const c=contract(),t=tab.review||'Generated JSON',entries=c[fieldCollection]||[],record=entries[fieldIndex]||{};return `<div class="editor-layout"><section class="card"><div class="card-heading"><h3>JSON Preview</h3><div class="actions">${btn('Format','format-json','code','small')}${S.approved?btn('Download','download','download','small','data-kind="contract"'):''}</div></div>${tabs('review',['Generated JSON','Schema View','Table View','Validation Issues'])}<div class="panel-body">${t==='Generated JSON'?`<div class="json-editor"><textarea id="canonical-editor" aria-label="Canonical JSON editor" spellcheck="false">${esc(S.draft.tester_editor||'{}')}</textarea><div class="editor-meta"><span id="save-status">Saved draft</span><span>JSON · tester-1</span></div></div>`:t==='Schema View'?`<pre class="code-block">${esc(pretty({schema_version:'tester-1',sources:'Original extracted content and provenance',requirements:'Source-linked requirements',parameters:'Reviewed type, unit, limits, domain and requirement_id',samples:'Observed parameter values',audit:'Recorded extraction and review events'}))}</pre>`:t==='Table View'?dataTable(c.parameters||[]):note('The existing backend validates JSON structure, constraints, and client context when you choose Validate & Continue. A reviewer name is required.','warning')}</div><div class="review-bar"><div class="field"><label for="canonical-reviewer">Reviewed by</label><input id="canonical-reviewer" placeholder="Enter reviewer name" value="${esc(reviewer)}"></div>${btn('Validate & Continue','approve-contract','shield','primary')}</div></section><aside class="card editor-fields"><h3>Field Editor</h3><div class="segmented">${[['parameters','Parameter'],['requirements','Requirement'],['samples','Sample']].map(([key,label])=>`<button class="${fieldCollection===key?'active':''}" data-action="field-collection" data-value="${key}">${label}</button>`).join('')}</div>${entries.length?`<div class="field"><label for="field-record">Select record</label><select id="field-record">${entries.map((r,i)=>`<option value="${i}" ${i===fieldIndex?'selected':''}>${esc(r.id||r.name||r.parameter||`Record ${i+1}`)}</option>`).join('')}</select></div>${Object.entries(record).filter(([k,v])=>!['metadata','attributes'].includes(k)).map(([k,v])=>`<div class="field"><label for="record-${esc(k)}">${esc(k.replaceAll('_',' '))}</label><input id="record-${esc(k)}" data-record-key="${esc(k)}" value="${esc(v===null?'null':short(v))}" ${k==='source'?'readonly':''}></div>`).join('')}${btn('Save Changes','save-record','tick','primary wide')}<p class="footnote">Editing invalidates the prior approval. Original source files remain intact.</p>`:empty('No records','Add structured records in the JSON editor.','file')}</aside></div><div class="flow-footer">${btn('Back','stage','back','','data-index="1"')}<span class="small muted">Client: ${esc(S.client.name)} · ${esc(scope.project)}</span></div>`}
function completePage(){const c=contract();if(!S.approved)return `<section class="card">${empty('Review is still required','Validate the current canonical JSON before proceeding.','shield',btn('Review JSON','stage','arrow','primary','data-index="2"'))}</section>`;return `<section class="card import-complete"><div class="success-mark">${icon('tick')}</div><h2>Your import is ready</h2><p>Canonical JSON has been reviewed and saved to <strong>${esc(scope.project)}</strong>.<br>Choose the next step in your engineering workflow.</p><div class="summary-grid">${[['Sources',c.sources],['Requirements',c.requirements],['Parameters',c.parameters]].map(([label,records])=>`<div class="summary-stat"><strong>${(records||[]).length}</strong><small>${label}</small></div>`).join('')}</div><div class="actions">${btn('Run Smart Check','goto-check','check','primary')}${btn('Generate Tests','goto-generation','spark')}${btn('Download JSON','download','download','','data-kind="contract"')}</div></section><div class="flow-footer">${btn('Back to Review','stage','back','','data-index="2"')}${btn('View project','goto-projects','arrow')}</div>`}
function findingRows(){const output=verification(),rows=[];(output.findings||[]).forEach((f,i)=>rows.push({index:i,id:`F-${String(i+1).padStart(3,'0')}`,severity:f.status==='FAIL'?'Error':f.status==='PASS'?'Info':'Warning',rule:(f.checks||[]).filter(c=>c.status!=='PASS').map(c=>c.rule||c.check||c.kind||c.constraint).filter(Boolean).join(', ')||'Parameter contract',parameter:f.parameter,description:f.reason||`${f.parameter}: ${f.status==='FAIL'?'observed value does not meet approved constraints':f.status==='PASS'?'observed value satisfies approved constraints':'insufficient evidence'}`,status:f.status,raw:f}));return rows}
function severity(value){return `<span class="severity ${value.toLowerCase()}">${icon(value==='Error'?'x':value==='Warning'?'warning':'info')}${value}</span>`}
function checkPage(){if(!S.approved)return heading('Verification','Run checks against your reviewed constraints and client rules.')+requireApproval();const t=tab.check||'Findings',rows=findingRows(),filtered=rows.filter(f=>(filter==='All'||f.severity===filter)&&JSON.stringify(f).toLowerCase().includes(query.toLowerCase())),v=verification();const pageSize=10,totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.min(page,totalPages);const shown=filtered.slice((page-1)*pageSize,page*pageSize);return heading('Verification','Run checks against approved constraints and client conventions.',btn('Run Check','run-check','check','primary')+(v.findings?btn('Export Report','download','download','','data-kind="verification"'):''))+`<section class="card"><div class="toolbar"><span class="small muted">${icon('file')} ${(contract().sources||[]).map(s=>esc(s.name)).join(', ')} · ${esc(scope.project)}</span>${badge(v.status||'Not run',v.status?'green':'')}</div>${tabs('check',['Findings','Summary','Coverage','Rule Details','Logs'])}${t==='Findings'?`<div class="verification-layout"><aside class="filters"><h3>Filters</h3><div class="filter-group"><strong>Severity</strong>${['All','Error','Warning','Info'].map(x=>`<label class="filter-option"><input type="radio" name="severity" value="${x}" ${filter===x?'checked':''}>${x} (${x==='All'?rows.length:rows.filter(r=>r.severity===x).length})</label>`).join('')}</div><div class="filter-group"><strong>Rule Set</strong>${badge('Parameter contracts','teal')}</div></aside><div><div class="toolbar"><h3>Findings <span class="inline-count">${filtered.length}</span></h3><label class="search-field">${icon('search')}<input id="finding-search" value="${esc(query)}" placeholder="Search findings…" aria-label="Search findings"></label></div>${shown.length?table(['ID','Severity','Rule','Parameter','Description','Status','Action'],shown.map(f=>tr([`<strong>${f.id}</strong>`,severity(f.severity),esc(f.rule),esc(f.parameter),esc(f.description),badge(f.status==='PASS'?'Passed':'Open',f.status==='PASS'?'green':'red'),btn('View','view-finding','eye','small',`data-index="${f.index}"`)]))):empty(v.findings?'No matching findings':'Ready to verify',v.findings?'Adjust your filters or search.':'Run a check to evaluate observed values against the approved contract.','check')}<div class="table-footer"><span>${filtered.length?`Showing ${(page-1)*pageSize+1} to ${Math.min(page*pageSize,filtered.length)} of ${filtered.length} findings`:'No findings to display'}</span><div class="pagination">${Array.from({length:totalPages},(_,i)=>`<button class="${page===i+1?'active':''}" data-action="paginate" data-page="${i+1}">${i+1}</button>`).join('')}</div></div></div></div>`:`<div class="panel-body">${t==='Summary'?`<div class="kpis">${['Error','Warning','Info'].map((name,i)=>`<div class="card kpi"><div><div class="kpi-value">${rows.filter(r=>r.severity===name).length}</div><div class="kpi-label">${name}</div></div></div>`).join('')}</div>${note(esc(v.note||'Run verification to populate the summary.'))}`:t==='Coverage'?dataTable((contract().parameters||[]).map(p=>({requirement:p.requirement_id,parameter:p.name,source:p.source})))+note('Declared requirement links only. Actual system execution coverage has not been measured.'):t==='Rule Details'?dataTable(v.client_checks||[])+note('This workspace runs approved parameter constraints and client conventions. Documented universal rule packs are configured in Rules Manager and executed through AI Agents.'): `<pre class="code-block">${esc(pretty(contract().audit||[]))}</pre>`}</div>`}</section>`}
function findingPage(){const index=Number(location.hash.split('/')[1]||0),f=findingRows()[index];if(!f)return heading('Finding details','This finding is no longer available.')+requireApproval();const t=tab.finding||'Overview',raw=f.raw,param=(contract().parameters||[]).find(p=>p.name===raw.parameter)||{},history=(S.draft.finding_reviews||[]).filter(r=>r.finding===index);return `<div class="breadcrumb"><button data-action="goto-check">${icon('back')}</button><a href="#check">Findings</a><span>›</span>${f.id}</div><div class="finding-header"><span class="finding-status">${icon(f.status==='PASS'?'tick':'x')}</span><div><h1>${f.id} <span class="muted">|</span> ${esc(f.parameter)} constraint review</h1><p>Rule: ${esc(f.rule)} &nbsp; | &nbsp; Parameter: ${esc(f.parameter)}</p></div>${badge(f.status==='PASS'?'Passed':'Open',f.status==='PASS'?'green':'red')}${btn('Re-check','run-check','refresh','small')}</div><div class="finding-grid"><nav class="detail-nav" aria-label="Finding sections">${[['Overview','report'],['Source Evidence','file'],['Rule Details','rules'],['Suggested Fix','edit'],['History','clock']].map(([name,ico])=>`<button class="${t===name?'active':''}" data-action="tab" data-key="finding" data-value="${name}">${icon(ico)}${name}</button>`).join('')}</nav><section class="card detail-section">${t==='Overview'?`<h3>Description</h3><p>${esc(f.description)}</p><h3>Approved constraint</h3><pre>${esc(pretty(param))}</pre><h3 class="mt">Evidence</h3><dl><dt>Actual value</dt><dd>${esc(short(raw.value))}</dd><dt>Source file</dt><dd>${esc(raw.source||param.source||'Not supplied')}</dd><dt>Source location</dt><dd>${esc(raw.row?`Row ${raw.row}`:param.row?`Row ${param.row}`:'No precise location recorded')}</dd></dl>`:t==='Source Evidence'?`<h3>Original source evidence</h3>${(contract().sources||[]).filter(s=>s.name===(raw.source||param.source)).map(s=>`<pre>${esc(s.content)}</pre>`).join('')||note('No source content is linked to this finding.')}`:t==='Rule Details'?`<h3>Executed constraint checks</h3><pre>${esc(pretty(raw.checks||[]))}</pre>`:t==='Suggested Fix'?note('The deterministic verifier does not propose an automatic correction. Review the actual value and expected constraints, edit the canonical draft, and approve it before rerunning.'):history.length?dataTable(history):empty('No review history','Record a review decision to add an audit entry.','clock')}</section><aside class="card detail-section"><h3>Review & Suggested Fix</h3>${note('Review source evidence before changing a constraint. Original source files are never modified.')}<div class="mb">${btn('Review canonical JSON','edit-contract','edit','primary wide')}</div>${field('Reviewer','finding-reviewer',reviewer)}<div class="field"><label for="finding-decision">Review decision</label><select id="finding-decision">${options(['Reviewed','Needs correction','Rejected'],'Reviewed')}</select></div><div class="field"><label for="finding-comment">Comments</label><textarea id="finding-comment" rows="3" placeholder="Add your review notes…"></textarea></div>${btn('Save review','save-finding','tick','wide',`data-index="${index}"`)}</aside></div>`}
function generationPage(){if(!S.approved)return heading('Test Generation','Turn reviewed requirements into traceable draft tests.')+requireApproval();const t=tab.generation||'Requirements',c=contract(),g=generation(),requirements=c.requirements||[];if(!selectedRequirements.size&&!generationPage.initialized){requirements.forEach(r=>selectedRequirements.add(r.id));generationPage.initialized=true}const reviewed=!!S.draft.generation_review;return heading('Test Generation','Select requirements, generate draft tests, and review before export.',btn('Generate Tests','generate','spark','primary'))+`<section class="card">${tabs('generation',['Requirements','Generation Configuration','Generated Tests','Validation','Export'])}<div class="panel-body">${t==='Requirements'?`${note('Select the requirements to include in this generation. Source links and expected outcomes are retained.')}<div class="toolbar"><h3>Source Requirements</h3><span class="inline-count">${selectedRequirements.size} selected</span></div>${requirements.length?table(['<input id="select-all-requirements" type="checkbox" aria-label="Select all requirements" '+(selectedRequirements.size===requirements.length?'checked':'')+'>','Requirement ID','Description','Source'],requirements.map(r=>tr([`<input type="checkbox" data-requirement="${esc(r.id)}" aria-label="Select ${esc(r.id)}" ${selectedRequirements.has(r.id)?'checked':''}>`,`<strong>${esc(r.id)}</strong>`,esc(r.text),esc(r.source||'—')])),'requirements-table'):empty('No requirements extracted','Add requirements and mappings in Import before generating tests.','rules')}`:t==='Generation Configuration'?`<div class="form-grid"><div class="field"><label>Testing level</label><select disabled><option>Parameter contract tests</option></select></div><div class="field"><label>Output framework</label><select disabled><option>pytest (Python)</option></select></div></div>${note('The existing generator produces nominal, boundary, and invalid-value contract cases. Dedicated HLT, LLT and integration generators are not implemented. Generated tests require an adapter to your real system.','warning')}${btn('Generate draft tests','generate','spark','primary')}`:t==='Generated Tests'?g.cases?.length?dataTable(g.cases):empty('No generated tests yet','Select requirements and choose Generate Tests.','spark'):t==='Validation'?`${note('Execution status: '+esc(g.execution_status||'Not generated')+'. No system tests have been executed.','warning')}${(g.unresolved||[]).map(x=>note(esc(x),'warning')).join('')}${dataTable(g.client_checks||[])}`:g.cases?`<div class="form-grid"><div>${field('Export reviewer','generation-reviewer',reviewer)}<label class="check-field"><input id="generation-confirm" type="checkbox">I reviewed the generated cases and unresolved constraints</label>${btn('Approve draft for export','review-generation','shield','primary')}</div><div>${note(reviewed?'Human review recorded. Download the approved draft below.':'Generated tests require a named human review before export.',reviewed?'success':'warning')}${reviewed?`<div class="actions">${btn('Pytest draft','download','code','','data-kind="code"')}${btn('Test cases JSON','download','download','','data-kind="tests"')}</div>`:''}</div></div>`:empty('Generate tests first','Reviewed test cases and code will be available for export here.','download')}</div></section>`}
const roleDescriptions={file_understanding:'Detect source structure, content, and unsupported elements.',json_transformation:'Normalize engineering content into the canonical representation.',client_configuration:'Apply client mappings, naming, and precision conventions.',standards_retrieval:'Retrieve documented rules and relevant standards evidence.',verification:'Review constraints and identify evidence-backed findings.',test_generation:'Propose structured test cases for human review.',traceability:'Connect requirements, source evidence, and generated artifacts.',reporting:'Prepare source-aware findings and review summaries.',orchestrator:'Coordinate validated agent handoffs and workflow recovery.'};
const roleName=r=>r.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
function agentsPage(){const a=S.settings.agents;if(agentRole){const config=agentDrafts[agentRole]||a[agentRole],t=tab.agent||'General';const logs=S.runs.flatMap(r=>r.logs||[]).filter(l=>l.agent===agentRole);return `<div class="breadcrumb"><button data-action="agent-overview">${icon('back')} AI Agents</button><span>›</span>${roleName(agentRole)}</div>`+heading(roleName(agentRole),roleDescriptions[agentRole],btn('Test Inference','test-agent','check','',`data-role="${agentRole}"`)+btn('Save Configuration','save-agent','tick','primary'))+`<section class="card">${tabs('agent',['General','Model Configuration','System Prompt','JSON Schema','Execution Settings','Logs & History'])}<div class="panel-body">${t==='General'?`<div class="flex-between"><h3>Independent Agent</h3>${badge(config.model?'Model assigned':'Unassigned',config.model?'teal':'orange')}</div>${note(esc(roleDescriptions[agentRole]))}<dl><dt class="muted small">Assigned model</dt><dd class="mono small">${esc(config.model||'No model selected')}</dd></dl>${localModelPanel()}${diagnosticPanel(agentRole)}`:t==='Model Configuration'?`<div class="form-grid"><div><div class="field"><label for="agent-model">Installed Ollama model</label><select id="agent-model"><option value="">Select an installed model</option>${options([...new Set([...(config.model?[config.model]:[]),...models])],config.model)}</select></div>${btn('Discover Installed Models','discover','refresh')}${diagnosticPanel(agentRole)}${modelsConnected&&!models.length?note('Ollama is connected, but no local models are available.','warning'):note('Model assignments are validated against the actual Ollama service before saving.')}</div></div>`:t==='System Prompt'?textArea('System instructions','agent-prompt',config.system_prompt):t==='JSON Schema'?textArea('Structured output JSON Schema','agent-schema',pretty(config.schema)):t==='Execution Settings'?`<div class="form-grid">${field('Temperature','agent-temperature',config.temperature,'number','min="0" max="2" step="0.1"')}${field('Timeout (seconds)','agent-timeout',config.timeout,'number','min="1" max="600"')}${field('Retries','agent-retries',config.retries,'number','min="0" max="3"')}</div>`:diagnosticPanel(agentRole)+dataTable(logs)}</div></section>`}return heading('AI Agent Studio','Nine independent roles. One coordinated engineering workflow.',btn('Connect / Refresh','discover','refresh'))+localModelPanel()+`${modelsConnected&&!models.length?note('Ollama is connected, but no local models are available.','warning'):''}<div class="grid-three">${S.roles.map(role=>{const config=a[role],diagnostic=S.model_tests?.[role],previous=S.runs.flatMap(r=>r.logs||[]).filter(l=>l.agent===role).at(-1);return `<section class="card agent-card"><div class="agent-top"><span class="agent-icon">${icon(role==='orchestrator'?'layers':'agents')}</span>${badge(modelsConnected&&models.includes(config.model)?'Available':config.model?'Not verified':'Unassigned',modelsConnected&&models.includes(config.model)?'green':'')}</div><h3>${roleName(role)}</h3><p>${esc(roleDescriptions[role])}</p><div class="agent-model">${icon('code')}<span>${esc(config.model||'No model assigned')}</span></div><p class="small">Last execution: ${esc(previous?.status||'Never run')} ? Inference test: ${esc(diagnostic?.model===config.model?diagnostic.status:'Not tested')}</p>${btn('Configure Agent','configure-agent','settings','',`data-role="${role}"`)}</section>`}).join('')}</div><section class="card mt"><div class="card-heading"><h3>Persisted Agent Runs</h3>${btn('Create Run','new-run','plus','primary small')}</div>${runTable()}</section>`}
function runTable(){return S.runs.length?table(['Run','Status','Sources','Review','Action'],S.runs.map(r=>tr([`<span class="mono">${esc(r.id.slice(0,12))}</span>`,badge(r.status,r.status==='approved'?'green':r.status==='failed'?'red':'blue'),String(r.cir.sources.length),esc(r.review?.reviewer||'Pending'),btn('Open','open-run','eye','small',`data-run="${r.id}"`)]))):empty('No agent runs yet','Import documents, configure installed models, then create a recoverable agent run.','agents')}
function configurationPage(){const t=tab.configuration||'General',c=S.client,p=S.settings.precision;return heading('Client Configuration',`Independent configuration for ${esc(c.name)}. Changes apply to future imports and runs.`,btn('New Client','new-client','plus'))+`<section class="card settings-page">${tabs('configuration',['General','File Mapping','Naming Conventions','Data Types & Precision','AI Models','Documentation','Export Templates'])}<div class="panel-body">${t==='General'?`<h3 class="section-title">Client Details</h3><div class="form-grid">${field('Client name','config-name',c.name)}${field('Industry','config-industry',c.industry)}${field('Contact','config-contact',c.contact)}<div class="field"><label for="config-language">Working language</label><select id="config-language">${options(['English','French','Arabic','Bilingual'],c.language)}</select></div><div class="field full"><label for="config-description">Programme description</label><textarea id="config-description" rows="3">${esc(c.description)}</textarea></div></div>${btn('Save Changes','save-client','tick','primary')}`:t==='File Mapping'?`<h3 class="section-title">Source to Canonical Mapping</h3><div class="form-grid">${textArea('Column aliases (JSON object)','config-aliases',pretty(c.column_aliases))}${textArea('Data type aliases (JSON object)','config-types',pretty(c.type_aliases))}<div class="field"><label for="config-delimiter">CSV delimiter</label><select id="config-delimiter">${options([',',';','|','\t'],c.csv_delimiter)}</select></div><div class="field"><label for="config-decimal">Source decimal separator</label><select id="config-decimal">${options(['.',','],c.decimal_separator)}</select></div></div>${btn('Validate & Save Mappings','save-client','tick','primary')}`:t==='Naming Conventions'?`<div class="form-grid">${field('Requirement identifier prefix','config-prefix',c.requirement_prefix)}${field('Normative words (comma separated)','config-keywords',c.normative_keywords.join(', '))}${field('Required fields (comma separated)','config-required',c.required_requirement_fields.join(', '))}<div class="field full"><label for="config-guidance">Writing guidance</label><textarea id="config-guidance" rows="4">${esc(c.writing_guidance)}</textarea></div>${textArea('Glossary (JSON object)','config-glossary',pretty(c.glossary))}</div>${btn('Save Conventions','save-client','tick','primary')}`:t==='Data Types & Precision'?`<h3 class="section-title">Numeric Precision Policy</h3><div class="form-grid"><div class="field"><label for="precision-scope">Apply to</label><select id="precision-scope">${options(['project','client'],'project')}</select></div><div class="field"><label for="precision-mode">Precision mode</label><select id="precision-mode">${options(['decimal_places','significant_digits','binary_bits'],p.mode)}</select></div>${field('Digits / binary bit width','precision-digits',p.digits,'number','min="1" max="1024"')}${field('Absolute comparison tolerance','precision-absolute',p.absolute_tolerance)}${field('Relative comparison tolerance','precision-relative',p.relative_tolerance)}</div>${note('Impact: future universal runs use this policy for numeric formatting proposals and equality checks. Existing run snapshots and original lexical values remain intact. Explicit parameter-contract constraints retain their own meanings.','warning')}${btn('Review & Apply Policy','save-precision','shield','primary')}`:t==='AI Models'?`${note('Independent Ollama models, prompts, JSON schemas and execution limits are managed per agent. Credentials for other providers use the existing local environment configuration.')}${btn('Open AI Agent Studio','goto-agents','agents','primary')}`:t==='Documentation'?`<h3 class="section-title">Client Reference Documents</h3>${dataTable(S.documents.filter(d=>d.guidance).map(d=>({document:d.name,source_hash:d.hash})))}${btn('Import Guidance','goto-import','upload')}`:`<h3 class="section-title">Available Export Adapters</h3>${note('JSON and CSV are built-in universal adapters. Pytest drafts use the existing parameter-contract generator. Unregistered formats are not offered.')}${textArea('Output templates (JSON object)','config-templates',pretty(S.settings.output_templates))}${btn('Save Templates','save-templates','tick','primary')}`}</div></section>`}
function rulesPage(){const t=tab.rules||'Rule Packs',packs=S.settings.rule_packs;let current=packs;if(t==='DO-178C')current=packs.filter(p=>p.id.toLowerCase().startsWith('do-178'));if(t==='Client Rules')current=packs.filter(p=>p.id.toLowerCase().startsWith('client'));if(t==='GT44 / Additional Standards')current=packs.filter(p=>p.id.toLowerCase().startsWith('gt44'));return heading('Rules Manager','Manage documented rules, client overrides, and execution evidence.')+`<section class="card">${tabs('rules',['Rule Packs','DO-178C','Client Rules','GT44 / Additional Standards','Custom Rules','Rule Conflicts','Execution History'])}<div class="panel-body">${t==='Custom Rules'?`<div class="field"><label for="rules-scope">Configuration scope</label><select id="rules-scope">${options(['project','client'],'project')}</select></div>${textArea('Rule packs JSON','rules-json',pretty(packs))}${note('Each pack requires ID, version, activation, source and rules. The existing validator rejects unsupported operators, duplicated IDs and conflicting configured bounds. Saving affects future runs.','warning')}${btn('Validate & Apply Rules','save-rules','shield','primary')}`:t==='Rule Conflicts'?`${note('The current saved settings have passed the existing range and prefix conflict validator. This does not establish satisfaction of mandatory aerospace certification objectives.','success')}<pre class="code-block">${esc(pretty(packs.map(p=>({id:p.id,active:p.active,source:p.source}))))}</pre>`:t==='Execution History'?runTable():current.length?table(['Pack','Version','Active','Rules','Source'],current.map(p=>tr([esc(p.id),esc(p.version),badge(p.active?'Active':'Disabled',p.active?'green':''),String(p.rules.length),esc(p.source)]))):empty('No documented rule packs','Add source-backed pack definitions in Custom Rules. The platform does not invent standard requirements.','rules',btn('Configure rule packs','rules-custom','plus','primary'))}</div></section>`}
function reportsPage(){const t=tab.reports||'Reports Overview',v=verification(),g=generation(),c=contract();return heading('Reports & Traceability','Keep source evidence, reviews, findings, and generated outputs connected.')+`<section class="card">${tabs('reports',['Reports Overview','Verification Reports','Requirement Traceability','Execution History','Export Center'])}<div class="panel-body">${t==='Reports Overview'?runTable()+note('Persisted runs retain their source hashes, configuration snapshot, agent messages, findings and human decisions.'):t==='Verification Reports'?v.findings?dataTable(v.findings)+`<div class="mt">${btn('Download Verification JSON','download','download','primary','data-kind="verification"')}</div>`:empty('No verification report','Run a check against the current approved contract.','report',btn('Open Check','goto-check','check','primary')):t==='Requirement Traceability'?dataTable((c.parameters||[]).map(p=>({requirement:p.requirement_id,parameter:p.name,source:p.source})))+dataTable(S.runs.flatMap(r=>r.cir.requirements.map(q=>({run:r.id,requirement:q.id,source_sha256:q.source_ref}))))+note('These are declared links and source lineage. Actual system execution coverage has not been measured.'):t==='Execution History'?dataTable(S.runs.flatMap(r=>r.audit.map(a=>({run:r.id,...a}))))+dataTable(S.draft.finding_reviews||[]):`<div class="grid-three">${S.approved?`<div class="card card-pad"><h3>Canonical Contract</h3><p class="footnote mb">Reviewed parameter-contract JSON.</p>${btn('Download JSON','download','download','','data-kind="contract"')}</div>`:''}${v.findings?`<div class="card card-pad"><h3>Verification Report</h3><p class="footnote mb">Observed values and executed constraint checks.</p>${btn('Download JSON','download','download','','data-kind="verification"')}</div>`:''}${g.cases?`<div class="card card-pad"><h3>Generated Tests</h3><p class="footnote mb">Human review is required before draft export.</p>${S.draft.generation_review?btn('Download Pytest','download','download','','data-kind="code"'):btn('Review generated draft','generation-export','shield')}</div>`:''}${S.runs.filter(r=>r.status==='approved').map(r=>`<div class="card card-pad"><h3>Agent Run ${esc(r.id.slice(0,8))}</h3><p class="footnote mb">Approved universal workflow evidence.</p><div class="actions">${r.configuration.export_formats.map(k=>btn(k.toUpperCase(),'download-run','download','small',`data-run="${r.id}" data-kind="${esc(k)}"`)).join('')}</div></div>`).join('')}</div>${!S.approved&&!S.runs.length?empty('No approved exports yet','Complete and review an import or agent run to enable exports.','download'):''}`}</div></section>`}
function showDialog(title,body,footer=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('x')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;d.showModal()}
function closeDialog(){$('#dialog').close()}
async function rememberReviewer(value){reviewer=value.trim();sessionStorage.setItem('sx-reviewer',reviewer);sync()}
async function saveEditor(){clearTimeout(editorTimer);if(editorPending===null)return editorSave;const text=editorPending;editorPending=null;editorSave=editorSave.catch(()=>{}).then(async()=>{try{S=await request('draft',{text,step:2});const status=$('#save-status');if(status)status.textContent='Saved draft ? review required';sync()}catch(e){if(editorPending===null)editorPending=text;toast('Draft not saved: '+e.message,true);throw e}});return editorSave}
async function changeScope(next){await saveEditor();scope=next;localStorage.setItem('sx-scope',JSON.stringify(scope));stage=null;files=[];selectedRequirements.clear();generationPage.initialized=false;agentRole=null;models=[];modelsConnected=false;agentDrafts={};$('#service-status').textContent='Ollama ? Not checked';$('.status-dot').classList.remove('online');try{await load()}catch(e){toast(e.message,true)}}
async function filePayload(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return {name:file.name,data:btoa(binary)}}
function addFiles(newFiles){const proposed=[...files,...newFiles];if(proposed.some(f=>f.size>10*1024*1024)||proposed.reduce((a,f)=>a+f.size,0)>50*1024*1024){toast('Maximum 10 MB per file and 50 MB combined.',true);return}files=proposed.filter((f,i,all)=>all.findIndex(x=>x.name===f.name&&x.size===f.size&&x.lastModified===f.lastModified)===i);render()}
function setupDrop(){const drop=$('#dropzone');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragover')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragover'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragover');addFiles([...e.dataTransfer.files])});$('#file-input').addEventListener('change',e=>addFiles([...e.target.files]))}
async function download(kind,run){const path=run?'run-export':'download';const res=await fetch('/api/'+path+'?'+new URLSearchParams({...scope,kind,...(run?{run}:{})}));if(!res.ok){const result=await res.json();throw new Error(result.error)}const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(res.headers.get('Content-Disposition')||'').match(/filename="([^"]+)"/)?.[1]||'sx-export';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function read(id,fallback){const el=$('#'+id);return el?el.value:fallback}
const actions={
 'toggle-menu':()=>$('#sidebar').classList.toggle('open'),
 'close-dialog':closeDialog,
 'browse':()=>$('#file-input').click(),
 'remove-file':el=>{files.splice(Number(el.dataset.index),1);render()},
 'tab':async el=>{await saveEditor();tab[el.dataset.key]=el.dataset.value;render()},
 'stage':async el=>{await saveEditor();stage=Number(el.dataset.index);if(stage>0&&!S.draft.tester_json)return;render()},
 'convert':async()=>{const pasted=read('paste-source','').trim();let inputs=await Promise.all(files.map(filePayload));if(pasted){let name='pasted_text.txt';try{JSON.parse(pasted);name='pasted_text.json'}catch{}inputs.push({name,data:btoa(unescape(encodeURIComponent(pasted)))})}if(!inputs.length)throw new Error('Choose a source file or paste requirements to continue');const result=await request('import',{files:inputs,provider:read('import-provider','deterministic'),guidance:$('#as-guidance').checked});S=result;stage=1;selectedRequirements.clear();generationPage.initialized=false;sync();render();toast('Source files imported and saved to this project.')},
 'format-json':()=>{const el=$('#canonical-editor');if(!el)return;el.value=pretty(JSON.parse(el.value));editorPending=el.value;return saveEditor()},
 'field-collection':async el=>{await saveEditor();fieldCollection=el.dataset.value;fieldIndex=0;render()},
 'save-record':async()=>{await saveEditor();const c=contract(),record=c[fieldCollection][fieldIndex];document.querySelectorAll('[data-record-key]').forEach(el=>{const key=el.dataset.recordKey;if(key==='source')return;const old=record[key];let value=el.value;if(typeof old==='number'){if(value.trim()===''||!Number.isFinite(Number(value)))throw new Error(key+' requires a finite number');value=Number(value)}else if(typeof old==='boolean'){if(!['true','false'].includes(value))throw new Error(key+' must be true or false');value=value==='true'}else if(old===null||typeof old==='object')value=JSON.parse(value);record[key]=value});await action('draft',{text:pretty(c),step:2},'Record saved. Review the updated JSON before approval.')},
 'approve-contract':async()=>{await saveEditor();const name=read('canonical-reviewer','');await rememberReviewer(name);await action('approve',{reviewer:name},'Canonical JSON validated and reviewed.');if(S.approved){stage=3;render()}},
 'edit-contract':()=>{stage=2;location.hash='import'},
 'run-check':()=>action('verify',{verification_profile:$('#verification-profile')?.value||'low_level_requirements',verification_mode:$('#verification-mode')?.value||'deterministic',custom_check:{parameter:read('verification-parameter',''),expected:read('verification-expected',''),prompt:read('verification-prompt','')}},'Verification completed with the selected configuration.'),
 'view-finding':el=>{tab.finding='Overview';location.hash='finding/'+el.dataset.index},
 'paginate':el=>{page=Number(el.dataset.page);render()},
 'save-finding':async el=>{const name=read('finding-reviewer','');await rememberReviewer(name);await action('finding-review',{index:Number(el.dataset.index),reviewer:name,decision:read('finding-decision'),comment:read('finding-comment')},'Finding review recorded.')},
 'generate':async()=>{await action('generate',{requirements:[...selectedRequirements]},'Draft tests generated. System execution has not been run.');if(generation().cases){tab.generation='Generated Tests';render()}},
 'review-generation':async()=>{if(!$('#generation-confirm').checked)throw new Error('Confirm that you reviewed the cases and unresolved constraints');const name=read('generation-reviewer','');await rememberReviewer(name);await action('review-generation',{reviewer:name},'Generated draft approved for export.')},
 'download':el=>download(el.dataset.kind),
 'download-run':el=>download(el.dataset.kind,el.dataset.run),
 'discover':async()=>{await refreshModels(true);if(!modelsConnected)throw new Error(modelsError||'Ollama unavailable');toast(models.length?'Installed Ollama models retrieved.':'Ollama is connected, but no local models are available.')},
 'configure-agent':el=>{agentRole=el.dataset.role;tab.agent='General';render()},
 'agent-overview':()=>{agentRole=null;render()},
 'save-agent':async()=>{const config={...(agentDrafts[agentRole]||S.settings.agents[agentRole])},t=tab.agent||'General';if(t==='Model Configuration')config.model=read('agent-model','');if(t==='System Prompt')config.system_prompt=read('agent-prompt');if(t==='JSON Schema')config.schema=JSON.parse(read('agent-schema'));if(t==='Execution Settings'){config.temperature=Number(read('agent-temperature'));config.timeout=Number(read('agent-timeout'));config.retries=Number(read('agent-retries'))}const saved=await action('settings',{settings:{agents:{...S.settings.agents,[agentRole]:config}},scope:'project'},'Agent configuration validated and saved.');if(saved)delete agentDrafts[agentRole]},
 'save-client':async()=>{const c={...S.client},t=tab.configuration||'General';if(t==='General')Object.assign(c,{name:read('config-name'),industry:read('config-industry'),contact:read('config-contact'),language:read('config-language'),description:read('config-description')});if(t==='File Mapping')Object.assign(c,{column_aliases:JSON.parse(read('config-aliases')),type_aliases:JSON.parse(read('config-types')),csv_delimiter:read('config-delimiter'),decimal_separator:read('config-decimal')});if(t==='Naming Conventions')Object.assign(c,{requirement_prefix:read('config-prefix'),normative_keywords:read('config-keywords').split(',').map(x=>x.trim()).filter(Boolean),required_requirement_fields:read('config-required').split(',').map(x=>x.trim()).filter(Boolean),writing_guidance:read('config-guidance'),glossary:JSON.parse(read('config-glossary'))});await action('client',{profile:c},'Client configuration saved. Reimport sources to apply this revision.')},
 'save-precision':()=>{const policy={mode:read('precision-mode'),digits:Number(read('precision-digits')),absolute_tolerance:read('precision-absolute'),relative_tolerance:read('precision-relative')},level=read('precision-scope');showDialog('Review precision policy',`<p>Apply this policy to future ${esc(level)} runs? Existing source values and run snapshots will be retained.</p><pre class="code-block mt">${esc(pretty({current:S.settings.precision,proposed:policy}))}</pre>`,btn('Cancel','close-dialog')+btn('Apply policy','apply-precision','tick','primary'));actions['apply-precision']=async()=>{closeDialog();await action('settings',{settings:{precision:policy},scope:level},'Precision policy validated and saved.')}},
 'save-templates':()=>action('settings',{settings:{output_templates:JSON.parse(read('config-templates'))},scope:'project'},'Export templates saved.'),
 'save-rules':()=>action('settings',{settings:{rule_packs:JSON.parse(read('rules-json'))},scope:read('rules-scope')},'Rule packs validated and saved.'),
 'rules-custom':()=>{tab.rules='Custom Rules';render()},
 'generation-export':()=>{tab.generation='Export';location.hash='generation'},
 'new-project':()=>showDialog('Create Project',`${field('Project name','new-project-name','','text','placeholder="Flight Control Computer (FCC)"')}<p>The project gets its own documents, canonical draft, runs, and settings overrides.</p>`,btn('Cancel','close-dialog')+btn('Create Project','create-project','plus','primary')),
 'create-project':async()=>{const name=read('new-project-name','').trim();if(!name)throw new Error('Enter a project name');await saveEditor();const next={...scope,project:name};await request('project',next);closeDialog();await changeScope(next);location.hash='projects';toast('Project created.')},
 'open-project':el=>changeScope({...scope,project:el.dataset.project}),
 'new-client':()=>showDialog('Create Client',field('Client name','new-client-name')+field('Industry / programme','new-client-industry','Aerospace'),btn('Cancel','close-dialog')+btn('Create Client','create-client','plus','primary')),
 'create-client':async()=>{const result=await request('create-client',{profile:{name:read('new-client-name'),industry:read('new-client-industry')}});closeDialog();await changeScope({client:result.created_client,project:'default'});toast('Client created.')},
 'profile':()=>showDialog('Reviewer Profile',field('Reviewer name','profile-name',reviewer)+note('Local review attribution. No enterprise identity provider is configured.'),btn('Cancel','close-dialog')+btn('Save Profile','save-profile','tick','primary')),
 'save-profile':async()=>{await rememberReviewer(read('profile-name',''));closeDialog();render()},
 'notifications':()=>showDialog('Notifications',S.draft.tester_json&&!S.approved?note('Canonical JSON needs human review before checking or generating tests.','warning'):note('No pending canonical review in this project.','success'),btn('Close','close-dialog')),
 'new-run':()=>showDialog('Create Agent Run',`<p>Select persisted source documents. All nine roles use the saved model assignments. The run pauses for human review before export.</p><div class="mt">${S.documents.map(d=>`<label class="check-field"><input type="checkbox" data-run-source="${d.hash}" checked>${esc(d.name)}</label>`).join('')||note('Import source documents first.')}</div>`,btn('Cancel','close-dialog')+btn('Create Run','create-run','plus','primary')),
 'create-run':async()=>{const docs=[...document.querySelectorAll('[data-run-source]:checked')].map(el=>el.dataset.runSource);closeDialog();await action('new-run',{documents:docs},'Canonical agent run created.')},
 'open-run':el=>openRun(el.dataset.run),
 'execute-run':el=>runAction('execute-run',el),
 'recover-run':el=>runAction('recover-run',el),
 'approve-run':el=>runAction('approve-run',el),
 'reject-run':el=>runAction('reject-run',el),
 'search':()=>searchDocuments()
};
async function runAction(actionName,el){const id=el.dataset.run,name=read('run-reviewer',reviewer),reason=read('run-reason','');closeDialog();await rememberReviewer(name);await action(actionName,{run:id,reviewer:name,reason},'Run state saved.');openRun(id)}
function openRun(id){const r=S.runs.find(r=>r.id===id);if(!r)return;showDialog('Agent Run '+esc(r.id.slice(0,12)),`<div class="flex-between"><strong>Status</strong>${badge(r.status,r.status==='failed'?'red':r.status==='approved'?'green':'blue')}</div>${r.error?note(esc(r.error),'warning'):''}<div class="actions mt">${['ready','failed'].includes(r.status)?btn('Run / Resume','execute-run','agents','primary',`data-run="${r.id}"`):''}${['failed','rejected'].includes(r.status)?btn('Recover','recover-run','refresh','',`data-run="${r.id}"`):''}</div><details class="option-details"><summary>Execution Logs</summary><pre class="code-block mt">${esc(pretty(r.logs))}</pre></details><details class="option-details"><summary>Agent Messages</summary><pre class="code-block mt">${esc(pretty(r.messages))}</pre></details><details class="option-details"><summary>Rule Findings & Numeric Proposals</summary><pre class="code-block mt">${esc(pretty({findings:r.findings,numeric:r.numeric_format_proposals}))}</pre></details><details class="option-details"><summary>Canonical JSON & Source Lineage</summary><pre class="code-block mt">${esc(pretty(r.cir))}</pre></details>${r.status==='human_review'?`<div class="mt">${field('Reviewer','run-reviewer',reviewer)}${field('Reason / correction request','run-reason')}</div>`:''}`,btn('Close','close-dialog')+(r.status==='human_review'?btn('Reject','reject-run','x','danger',`data-run="${r.id}"`)+btn('Approve','approve-run','shield','primary',`data-run="${r.id}"`):''))}
function searchDocuments(){const q=$('#global-search').value.trim().toLowerCase();if(!q)return;const docs=S.documents.filter(d=>(d.name+' '+d.text).toLowerCase().includes(q));showDialog('Project Search',docs.length?table(['Document','Source'],docs.map(d=>tr([esc(d.name),esc(d.hash.slice(0,16))]))):empty('No documents found','Try a different keyword in the current project.','search'),btn('Close','close-dialog'))}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const name=el.dataset.action;try{if(name.startsWith('goto-')){await saveEditor();location.hash=name.slice(5);return}if(actions[name]){el.disabled=true;try{await actions[name](el)}finally{el.disabled=false}}}catch(error){toast(error.message,true)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='client-select'){await changeScope({client:e.target.value,project:'default'});return}if(e.target.id==='project-select'){await changeScope({...scope,project:e.target.value});return}if(e.target.id==='verification-profile'){localStorage.setItem('sx-verification-profile',e.target.value);render();return}if(e.target.id==='verification-mode'){localStorage.setItem('sx-verification-mode',e.target.value);render();return}if(e.target.id==='field-record'){fieldIndex=Number(e.target.value);render();return}if(e.target.name==='severity'){filter=e.target.value;page=1;render();return}if(e.target.dataset.requirement){e.target.checked?selectedRequirements.add(e.target.dataset.requirement):selectedRequirements.delete(e.target.dataset.requirement);return}if(e.target.id==='select-all-requirements'){selectedRequirements=new Set(e.target.checked?(contract().requirements||[]).map(r=>r.id):[]);render()}}catch(error){toast(error.message,true)}});
document.addEventListener('input',e=>{if(e.target.id==='canonical-editor'){editorPending=e.target.value;clearTimeout(editorTimer);const status=$('#save-status');if(status)status.textContent='Saving…';editorTimer=setTimeout(()=>saveEditor().catch(()=>{}),650)}if(e.target.id==='finding-search'){query=e.target.value;page=1;const start=e.target.selectionStart;render();const input=$('#finding-search');input.focus();input.setSelectionRange(start,start)}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus()}if(e.key==='Enter'&&e.target.id==='global-search')searchDocuments()});
window.addEventListener('hashchange',async()=>{try{await saveEditor();$('#sidebar').classList.remove('open');render();$('#main').focus({preventScroll:true});window.scrollTo(0,0)}catch{}});
window.addEventListener('beforeunload',e=>{if(editorPending!==null){e.preventDefault();e.returnValue=''}});
load().catch(error=>{content.innerHTML=heading('Unable to open workspace','The backend could not load this client or project.')+note(esc(error.message),'warning')+btn('Reset client selection','reset-scope','refresh','primary');actions['reset-scope']=()=>changeScope({client:'default',project:'default'})});
function diagnosticPanel(role){const result=S.model_tests?.[role];if(!result)return note('No inference diagnostic has been run for this role. Save an installed model, then choose Test Inference.');const current=result.model===S.settings.agents[role].model;return `<div class="mt"><h3>Last Inference Diagnostic</h3>${note(`${esc(result.model)} · ${esc(result.status)} · ${esc(result.at)}${!current?' · Saved model has since changed.':''}`,result.status==='passed'&&current?'success':'warning')}${result.error?note(esc(result.error),'warning'):''}<details class="option-details"><summary>Validated response & timing</summary><pre class="code-block mt">${esc(pretty({response:result.result,logs:result.logs}))}</pre></details><p class="footnote">A diagnostic verifies local inference and JSON schema conformance, not engineering correctness.</p></div>`}
function localModelPanel(){return `<section class="card model-setup mb"><div class="card-heading"><div><h3>Local Model Runtime</h3><p class="footnote">Ollama · Installed models are discovered from your local service.</p></div>${badge(modelsConnected?'Connected':'Disconnected',modelsConnected?'green':'orange')}</div><div class="panel-body"><div class="model-setup-grid"><div><div class="field"><label for="setup-model">Installed completion model</label><select id="setup-model"><option value="">${models.length?'Select a local model':'No models discovered'}</option>${options(models,agentRole?S.settings.agents[agentRole].model:'')}</select></div><div class="actions">${btn(agentRole?'Assign to this Agent':'Assign to All 9 Agents','assign-model','agents','primary')}${btn('Test Inference','test-agent','check','',`data-role="${agentRole||'file_understanding'}"`)}</div></div><div><div class="actions">${btn('Connect / Refresh','discover','refresh')}${!modelsConnected?btn('Start Ollama','start-ollama','plus'):''}</div>${modelsError?note(esc(modelsError),'warning'):note(models.length?`${models.length} installed model${models.length===1?'':'s'}. One model can serve all nine roles; each role keeps independent prompts and schemas.`:'Ollama is connected, but no local models are available. Install a local model below.',models.length?'':'warning')}</div></div><details class="option-details"><summary>Install another local model / use downloaded weights</summary><p>Enter an exact model tag from the Ollama registry. Downloads run in the background and report real progress. Check available disk space before installing large weights.</p><div class="model-install-row mt"><div class="field"><label for="pull-model-name">Ollama registry model tag</label><input id="pull-model-name" placeholder="Enter a model name and tag"></div>${btn('Download Model','pull-model','download','primary')}</div>${downloadJob?downloadProgress():''}<p>For GitHub/Hugging Face weights: download a supported GGUF, create a Modelfile with <code>FROM /path/to/model.gguf</code>, then run <code>ollama create my-local-model -f Modelfile</code>. Reconnect to select it here. A Git repository alone is not a runnable model.</p><p><a href="https://ollama.com/library" target="_blank" rel="noopener noreferrer">Ollama model library ↗</a> · <a href="https://docs.ollama.com/import" target="_blank" rel="noopener noreferrer">Official GGUF import instructions ↗</a></p></details></div></section>`}
function downloadProgress(){const j=downloadJob,percent=j.total?Math.min(100,Math.round(100*j.completed/j.total)):0;return `<div class="note ${j.status==='failed'?'warning':j.status==='completed'?'success':''}"><strong>${esc(j.model)} · ${esc(j.status)}</strong><p>${esc(j.message)}</p>${j.total?`<progress max="100" value="${percent}"></progress><small>${percent}% · ${(j.completed/1024**3).toFixed(2)} / ${(j.total/1024**3).toFixed(2)} GB</small>`:''}</div>`}
async function refreshModels(renderAfter=true){try{const result=await request('models',{});models=result.models||[];modelsConnected=!!result.connected;modelsError=result.error||'';$('#service-status').textContent=modelsConnected?`Ollama · ${models.length} model${models.length===1?'':'s'}`:'Ollama · Unavailable';$('.status-dot').classList[modelsConnected?'add':'remove']('online');if(renderAfter&&(route==='agents'||route==='dashboard'))render()}catch(error){modelsConnected=false;modelsError=error.message;if(renderAfter&&route==='agents')render()}}
async function pollDownload(){if(!downloadJob||downloadJob.status!=='running')return;try{downloadJob=await request('download-status',{job:downloadJob.id});const region=$('#download-progress');if(region)region.innerHTML=downloadProgress();if(downloadJob.status==='completed'){await refreshModels(true);toast('Model installed. Assign it to an agent and run Test Inference.')}else if(downloadJob.status==='failed')toast(downloadJob.message,true);else setTimeout(pollDownload,1500)}catch(error){toast(error.message,true)}}
actions['start-ollama']=async()=>{const result=await request('start-ollama',{});toast(result.message||'Ollama already connected.');setTimeout(()=>refreshModels(true),2500)};
actions['assign-model']=async()=>{const model=read('setup-model','');if(!model)throw new Error('Choose an installed model first');const saved=await action('assign-model',{model,roles:agentRole?[agentRole]:S.roles},'Installed model assigned. Test inference to verify execution.');if(saved&&agentRole)delete agentDrafts[agentRole]};
actions['test-agent']=async el=>{const role=el.dataset.role||agentRole||'file_understanding';if(!S.settings.agents[role].model)throw new Error('Assign and save an installed model before testing inference');toast('Running real local inference. Initial model loading may take a moment.');const testedScope={...scope};const result=await request('test-agent',{role});if(scope.client!==testedScope.client||scope.project!==testedScope.project){toast('Inference diagnostic saved in the previously selected project.');return}S=result.state;render();if(result.diagnostic.status!=='passed')throw new Error(result.diagnostic.error||'Inference test failed');toast(roleName(role)+': local inference and JSON schema validation passed.')};
actions['pull-model']=async()=>{const model=read('pull-model-name','').trim();if(!model)throw new Error('Enter a model tag from the Ollama registry');downloadJob=await request('pull-model',{model});const parent=$('#pull-model-name')?.closest('details');if(parent){const progress=document.createElement('div');progress.id='download-progress';parent.appendChild(progress);progress.innerHTML=downloadProgress()}pollDownload()};

function enhancePage(){if(!S||!content)return;
 if(route!=='import'){$('#workflow-quickbar').innerHTML=''}
 const nav=$('#nav');if(nav&&!nav.dataset.premiumShell){const groups=[['workspace','Workspace',['dashboard','projects']],['workflow','Engineering',['import','check','generation']],['manage','AI & Configuration',['agents','configuration','rules']],['insights','Insights',['reports']]];nav.innerHTML=groups.map(([key,title,ids])=>`<div class="nav-section-label">${title}</div>${ids.map(id=>{const item=navItems.find(x=>x[0]===id),[name,ico,label]=item||[];return `<a class="nav-item ${route===name?'active':''}" href="#${name}" ${route===name?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${name==='import'&&!S.documents.length?'<span class="nav-badge">Start</span>':''}${name==='check'&&S.approved&&!S.draft.verification_output?'<span class="nav-badge">Next</span>':''}</a>`}).join('')}`).join('');nav.dataset.premiumShell='true'}
 if(route==='check'){const checkTabs=document.querySelector('[aria-label="check"]');if(checkTabs){const labels={Coverage:'Traceability','Rule Details':'Rules'};checkTabs.querySelectorAll('.tab').forEach(button=>{const label=button.dataset.value;button.textContent=labels[label]||label;button.dataset.value=labels[label]||label})}}
 if(route==='projects'&&!$('#project-level-segmented')){const block=content.querySelector('.project-levels');if(block){const records=[...(contract().requirements||[]),...(contract().parameters||[])];block.innerHTML=`<div class="card-heading"><div><h2>${esc(scope.project)} workspace</h2><p class="footnote">Use the level selector to focus the engineering view.</p></div>${badge(S.approved?'Approved contract':'Review required',S.approved?'green':'orange')}</div><div id="project-level-segmented" class="segmented-control">${testLevels.map(([level,label],i)=>`<button class="${i===0?'active':''}" data-project-level="${level}">${level}<span>${records.filter(r=>requirementLevel(r)===level).length}</span></button>`).join('')}</div><div id="project-level-content">${levelCards(records,'No records mapped to this level.')}</div>`;block.dataset.records=JSON.stringify(records)}}
 if(route==='projects'&&$('#project-level-segmented')&&!$('#project-level-segmented').dataset.bound){$('#project-level-segmented').dataset.bound='true';$('#project-level-segmented').addEventListener('click',event=>{const button=event.target.closest('[data-project-level]');if(!button)return;const level=button.dataset.projectLevel;const records=JSON.parse($('#project-levels')?.dataset.records||$('.project-levels')?.dataset.records||'[]');document.querySelectorAll('[data-project-level]').forEach(x=>x.classList.toggle('active',x===button));const rows=records.filter(r=>requirementLevel(r)===level);$('#project-level-content').innerHTML=rows.length?table(['ID','Description','Source'],rows.map(r=>tr([`<strong>${esc(r.id||r.name||'—')}</strong>`,esc(r.text||r.description||r.name||'—'),esc(r.source||r.source_ref||'—')]))):empty(`No ${level} records yet`,'Import or configure records for this level.','layers')})}
 if(route==='agents'&&!$('#agent-studio-guidance')){const anchor=content.querySelector('.model-setup');if(anchor)anchor.insertAdjacentHTML('beforebegin',`<section id="agent-studio-guidance" class="note agent-guidance"><strong>Agent Studio</strong><span>Select an agent to edit its prompt, model, schema, and execution settings. Every model is checked against the live Ollama service before saving.</span></section>`)}
 if(route==='generation'&&S.approved&&!$('#generation-live-config')){const anchor=content.querySelector('.panel-body');if(anchor){anchor.insertAdjacentHTML('afterbegin',`<section id="generation-live-config" class="card live-config"><div class="card-heading"><div><span class="workflow-kicker">OUTPUT CONFIGURATION</span><h3>How should the test file be generated?</h3><p class="footnote">These settings are included in the generation snapshot and are checked before export.</p></div>${badge('Ready to configure','blue')}</div><div class="form-grid"><div class="field"><label>Levels included</label>${testLevels.map(([level,label])=>`<label class="check-field"><input type="checkbox" class="generation-level" value="${level}" checked><span>${level} · ${label}</span></label>`).join('')}</div><div class="field"><label for="generation-output-type">Output format</label><select id="generation-output-type">${options(['pytest','json','csv','xlsx','xlsm','ptu'],'pytest')}</select><small>Pick the file type used by your test or rule workflow.</small></div>${textArea('Rules for the generated output','generation-output-rules','Example: one case per ID, include precondition, expected result, pass/fail criteria, and source reference.',120)}${textArea('Example file or template (optional)','generation-source-example','',120)}</div></section>`)}}
 if(route==='configuration'&&!$('#configuration-layers')){const anchor=content.querySelector('.settings-page .panel-body');if(anchor){anchor.insertAdjacentHTML('afterbegin',`<section id="configuration-layers" class="card live-config"><div class="card-heading"><div><span class="workflow-kicker">TWO LAYERS</span><h3>Generic baseline and client-specific rules</h3><p class="footnote">Generic rules follow DO-178C practice. Specific rules apply only to this client, programme, or developer standard.</p></div>${badge('Independent','blue')}</div><div class="form-grid"><div>${textArea('Generic baseline (DO-178C)','config-generic-rules',S.settings.configuration_layers?.generic||'DO-178C baseline: requirements must be uniquely identified, verifiable, traceable, and supported by objective evidence.',120)}</div><div>${textArea('Client / developer specific rules','config-specific-rules',S.settings.configuration_layers?.specific||'',120)}</div></div>${btn('Save both configuration layers','save-configuration-layers','tick','primary')}</section>`)}}
 if(route==='rules'&&!$('#rules-level-map')){const anchor=content.querySelector('.settings-page .panel-body')||content.querySelector('.card .panel-body');if(anchor){anchor.insertAdjacentHTML('afterbegin',`<section id="rules-level-map" class="card live-config"><div class="card-heading"><div><span class="workflow-kicker">LEVEL MAP</span><h3>Rules by engineering level</h3><p class="footnote">Review which rules apply to LLR, LLT, and HLT before executing a check.</p></div>${badge(`${(S.settings.rule_packs||[]).length} packs`,'blue')}</div><div class="level-strip">${testLevels.map(([level,label])=>`<div><strong>${level}</strong><span>${label}</span><b>${(S.settings.rule_packs||[]).filter(p=>JSON.stringify(p).toUpperCase().includes(level)).length||'—'}</b></div>`).join('')}</div></section>`)}}
 if(route==='reports'&&!$('#report-linked-evidence')){const v=verification(),anchor=content.querySelector('.panel-body');if(anchor){const findings=v.findings||[],fixes=findings.filter(f=>f.status!=='PASS').slice(0,8);anchor.insertAdjacentHTML('afterbegin',`<section id="report-linked-evidence" class="card live-config"><div class="card-heading"><div><span class="workflow-kicker">LINKED EVIDENCE</span><h3>What is linked and what can be fixed?</h3><p class="footnote">Every report points back to source files, requirement IDs, and the review action needed.</p></div>${badge(`${S.documents.length} files linked`,'blue')}</div>${table(['Linked files','Open issue','Suggested next action'],(fixes.length?fixes:[{parameter:'—',description:'No open findings',rule:'Review complete'}]).map(f=>tr([esc((S.documents||[]).map(d=>d.name).join(', ')||'No source file'),esc(f.description||f.parameter||'—'),esc(f.status==='PASS'?'Keep evidence linked':'Review source evidence and update the approved contract')])) )}</section>`)}}
}
actions['save-configuration-layers']=()=>action('settings',{settings:{configuration_layers:{generic:read('config-generic-rules',''),specific:read('config-specific-rules','')}},scope:'client'},'Generic and client-specific configuration saved.');
actions.tab=async el=>{await saveEditor();const value=(el.dataset.key==='check'&&el.dataset.value==='Traceability')?'Coverage':(el.dataset.key==='check'&&el.dataset.value==='Rules')?'Rule Details':el.dataset.value;tab[el.dataset.key]=value;render()};
actions.generate=async()=>{const levels=[...document.querySelectorAll('.generation-level:checked')].map(x=>x.value);const all=contract().requirements||[];const requirements=[...selectedRequirements].filter(id=>{const item=all.find(r=>r.id===id);return !levels.length||levels.includes(requirementLevel(item||{}))});if(!requirements.length)throw new Error('Select at least one requirement and one test level');await action('generate',{requirements,levels,output_type:read('generation-output-type','pytest'),output_rules:read('generation-output-rules',''),source_example:read('generation-source-example','')},'Draft tests generated with the selected levels and output configuration.');if(generation().cases){tab.generation='Generated Tests';render()}};
const pageObserver=typeof MutationObserver!=='undefined'?new MutationObserver(()=>{if(!document.body.classList.contains('busy'))enhancePage()}):null;if(pageObserver)pageObserver.observe(content,{childList:true});
document.addEventListener('input',e=>{if(!agentRole)return;const id=e.target.id,keys={'agent-prompt':'system_prompt','agent-model':'model','agent-schema':'schema','agent-temperature':'temperature','agent-timeout':'timeout','agent-retries':'retries'};if(!(id in keys))return;const draft=agentDrafts[agentRole]||structuredClone(S.settings.agents[agentRole]);try{draft[keys[id]]=id==='agent-schema'?JSON.parse(e.target.value):['agent-temperature','agent-timeout','agent-retries'].includes(id)?Number(e.target.value):e.target.value;agentDrafts[agentRole]=draft}catch{}});
